impl LocalAgentRuntime {
    pub(crate) fn root_permissions(&self) -> Option<Arc<ThreadConfigSnapshot>> {
        self.root_permissions.load_full()
    }

    pub(crate) async fn sync_root_permissions(&self, snapshot: ThreadConfigSnapshot) {
        // Once activated, also propagate a later restriction so children cannot retain Full Access.
        if !snapshot.full_access && self.root_permissions.load().is_none() {
            return;
        }
        if self.root_permissions().is_some_and(|current| {
            current.approval_policy == snapshot.approval_policy
                && current.approvals_reviewer == snapshot.approvals_reviewer
                && current.permission_profile == snapshot.permission_profile
                && current.environments == snapshot.environments
        }) {
            return;
        }
        self.root_permissions.store(Some(Arc::new(snapshot)));
        let Ok(manager) = self.upgrade() else {
            return;
        };
        for metadata in self.registry.live_agents() {
            let Some(thread_id) = metadata.agent_id else {
                continue;
            };
            let Ok(thread) = manager.get_thread(thread_id).await else {
                // Unloaded children read the latest owner snapshot when they resume.
                continue;
            };
            if !matches!(
                thread.session_source,
                SessionSource::SubAgent(SubAgentSource::ThreadSpawn { .. })
            ) {
                continue;
            }
            let Some(snapshot) = self.root_permissions() else {
                continue;
            };
            if let Err(error) = thread.session.apply_inherited_permissions(snapshot).await {
                tracing::warn!(%thread_id, %error, "failed to synchronize child permissions");
                thread
                    .session
                    .send_event_raw(codex_protocol::protocol::Event {
                        id: uuid::Uuid::now_v7().to_string(),
                        msg: codex_protocol::protocol::EventMsg::Warning(
                            codex_protocol::protocol::WarningEvent {
                                message: format!("Could not inherit root permissions: {error}"),
                            },
                        ),
                    })
                    .await;
            }
        }
    }

    pub(crate) async fn sync_child_permissions(&self, thread: &CodexThread) -> Result<(), String> {
        let _sync = self.root_permissions_sync.lock().await;
        if !matches!(
            thread.session_source,
            SessionSource::SubAgent(SubAgentSource::ThreadSpawn { .. })
        ) {
            return Ok(());
        }
        let Some(snapshot) = self.root_permissions() else {
            return Ok(());
        };
        Box::pin(thread.session.apply_inherited_permissions(snapshot)).await
    }
}

