//! Applies opt-in root permissions through the same constrained settings as user updates.

use super::session::Session;
use super::session::SessionConfiguration;
use super::session::SessionSettingsCommit;
use super::session::SessionSettingsUpdate;
use super::step_settings::ResolvedStepSettings;
use super::step_settings::StepSettingsUpdate;
use crate::codex_thread::ThreadConfigSnapshot;
use crate::config::ConstraintError;
use crate::config::ConstraintResult;
use crate::state::ActiveTurn;
use codex_protocol::models::PermissionProfileSnapshot;
use codex_protocol::protocol::AskForApproval;
use codex_protocol::protocol::EnvironmentConfigState;
use codex_protocol::protocol::TurnEnvironmentSelection;
use std::sync::Arc;

pub(super) struct InheritedPermissions {
    pub(super) approval_policy: AskForApproval,
    pub(super) permission_profile: codex_protocol::models::PermissionProfile,
}

pub(super) struct PreparedInheritedPermissions {
    permissions: InheritedPermissions,
    active_selections: Vec<TurnEnvironmentSelection>,
    settings: Option<ResolvedStepSettings>,
}

impl PreparedInheritedPermissions {
    pub(super) fn publish(self, session: &Session, active: Option<&ActiveTurn>) {
        session.mark_mcp_runtime_dirty();
        if let Some(task) = active.and_then(|active| active.task.as_ref())
            && let Some(settings) = self.settings
        {
            task.turn_context.extension_data.insert(self.permissions);
            task.turn_context
                .next_step_settings
                .store(Arc::new(settings));
        }
        session
            .services
            .turn_environments
            .update_selections(&self.active_selections);
    }
}

impl Session {
    pub(crate) fn refresh_inherited_tool_permissions(
        &self,
        step: &Arc<super::step_context::StepContext>,
    ) -> ConstraintResult<Arc<super::step_context::StepContext>> {
        if step
            .turn
            .extension_data
            .get::<InheritedPermissions>()
            .is_none()
        {
            return Ok(Arc::clone(step));
        }
        let latest = step.turn.next_step_settings.load_full();
        let mut selected = step.settings.selected().clone();
        selected.approval_policy.set(latest.approval_policy())?;
        selected.approvals_reviewer = latest.approvals_reviewer();
        let mut settings = ResolvedStepSettings::new(
            Arc::new(selected),
            Arc::clone(&step.settings.model_info),
            &self.features,
        );
        settings.mcp_approvals_reviewer_override = latest.mcp_approvals_reviewer_override;
        let mut refreshed = step.as_ref().clone();
        refreshed.settings = Arc::new(settings);
        refreshed.environments = self.services.turn_environments.snapshot_now();
        Ok(Arc::new(refreshed))
    }

    pub(super) fn sync_subagent_permissions<'a>(
        &'a self,
        commit: &'a SessionSettingsCommit,
    ) -> futures::future::BoxFuture<'a, ()> {
        Box::pin(async move {
            let configuration = &commit.configuration;
            if configuration.parent_thread_id.is_some()
                || matches!(
                    configuration.session_source,
                    codex_protocol::protocol::SessionSource::SubAgent(_)
                        | codex_protocol::protocol::SessionSource::Internal(_)
                )
                || !configuration
                    .original_config_do_not_use
                    .agent_inherit_full_access
            {
                return;
            }
            // Read current settings after admission so older commits cannot overwrite newer ones.
            let _sync = self
                .services
                .local_agent_runtime
                .root_permissions_sync
                .lock()
                .await;
            let snapshot = self.thread_config_snapshot().await;
            self.services
                .local_agent_runtime
                .sync_root_permissions(snapshot)
                .await;
        })
    }

    pub(crate) async fn apply_inherited_permissions(
        &self,
        root: Arc<ThreadConfigSnapshot>,
    ) -> Result<(), String> {
        let _persistence = super::thread_settings::acquire_persistence_lock(self).await;
        let updates = SessionSettingsUpdate {
            inherited_root_permissions: Some(root),
            ..Default::default()
        };
        let commit = Box::pin(self.update_settings(updates))
            .await
            .map_err(|error| error.to_string())?;
        super::thread_settings::emit_applied(
            self,
            uuid::Uuid::now_v7().to_string(),
            commit.snapshot,
        )
        .await;
        Ok(())
    }

    // Called while holding both active-turn and session-state locks. Nothing is published until
    // future settings and the running turn have both passed their existing constraints.
    pub(super) fn prepare_inherited_permissions(
        &self,
        updates: &mut SessionSettingsUpdate,
        current: &SessionConfiguration,
        active: Option<&ActiveTurn>,
    ) -> ConstraintResult<Option<PreparedInheritedPermissions>> {
        let Some(root) = updates.inherited_root_permissions.clone() else {
            return Ok(None);
        };
        let mut selections = current.environments.clone();
        let mut active_selections = self.services.turn_environments.selections();
        // Preserve each child's executor, cwd and workspace roots; adopt only owner permissions.
        for selection in selections.iter_mut().chain(active_selections.iter_mut()) {
            if let EnvironmentConfigState::Ready(config) = &mut selection.config {
                let owner = root
                    .environment_selections()
                    .iter()
                    .find(|owner| owner.environment_id == selection.environment_id);
                let profile = match owner.map(|owner| &owner.config) {
                    Some(EnvironmentConfigState::Ready(config)) => {
                        config.permission_profile.clone()
                    }
                    Some(EnvironmentConfigState::FromThread) => {
                        PermissionProfileSnapshot::legacy(root.permission_profile.clone())
                    }
                    Some(EnvironmentConfigState::Pending | EnvironmentConfigState::Failed(_))
                    | None => {
                        return Err(ConstraintError::InvalidValue {
                            field_name: "environments",
                            candidate: selection.environment_id.clone(),
                            allowed: "ready root-owned environment".into(),
                            requirement_source: codex_config::RequirementSource::Unknown,
                        });
                    }
                };
                config.permission_profile = profile;
            }
        }
        updates.step_settings = StepSettingsUpdate {
            approval_policy: Some(root.approval_policy),
            approvals_reviewer: Some(root.approvals_reviewer),
            ..Default::default()
        };
        updates.permission_profile = Some(root.permission_profile.clone());
        updates.environments = Some(codex_protocol::protocol::TurnEnvironmentSelections::new(
            current.cwd().clone(),
            selections,
        ));
        let candidate = self.apply_session_settings(current, updates)?;
        let settings = if let Some(task) = active.and_then(|active| active.task.as_ref()) {
            let current_settings = task.turn_context.next_step_settings.load_full();
            let selected = current_settings.selected().apply(
                &updates.step_settings,
                &candidate.step_settings_constraints(&active_selections),
            )?;
            let mut settings = ResolvedStepSettings::new(
                Arc::new(selected),
                Arc::clone(&current_settings.model_info),
                &self.features,
            );
            settings.mcp_approvals_reviewer_override = Some(root.approvals_reviewer);
            Some(settings)
        } else {
            None
        };
        let permissions = InheritedPermissions {
            approval_policy: candidate.step_settings.approval_policy.value(),
            permission_profile: candidate
                .thread_config_snapshot(active_selections.clone())
                .permission_profile,
        };
        Ok(Some(PreparedInheritedPermissions {
            permissions,
            active_selections,
            settings,
        }))
    }
}

