//! Exercises real spawning and live root permission changes for both multi-agent backends.

use anyhow::Result;
use codex_core::config::AgentRoleConfig;
use codex_features::Feature;
use codex_protocol::config_types::ApprovalsReviewer;
use codex_protocol::models::PermissionProfile;
use codex_protocol::protocol::AskForApproval;
use codex_protocol::protocol::EventMsg;
use codex_protocol::protocol::ThreadSettingsOverrides;
use core_test_support::responses;
use core_test_support::test_codex::test_codex;
use core_test_support::wait_for_event;
use pretty_assertions::assert_eq;
use serde_json::json;
use test_case::test_case;

fn body_contains(request: &wiremock::Request, text: &str) -> bool {
    let body = match request
        .headers
        .get("content-encoding")
        .and_then(|value| value.to_str().ok())
    {
        Some("zstd") => zstd::stream::decode_all(std::io::Cursor::new(&request.body)).ok(),
        _ => Some(request.body.clone()),
    };
    body.and_then(|body| String::from_utf8(body).ok())
        .is_some_and(|body| body.contains(text))
}

#[test_case(false, false; "v1 default")]
#[test_case(false, true; "v1 inheritance")]
#[test_case(true, false; "v2 default")]
#[test_case(true, true; "v2 inheritance")]
#[tokio::test(flavor = "multi_thread", worker_threads = 2)]
async fn subagent_permissions_follow_live_root_selection(v2: bool, enabled: bool) -> Result<()> {
    let server = responses::start_mock_server().await;
    let mut builder = test_codex()
        .with_model_info_override("gpt-5.6-sol", move |model| {
            model.multi_agent_version = Some(if v2 {
                codex_protocol::protocol::MultiAgentVersion::V2
            } else {
                codex_protocol::protocol::MultiAgentVersion::V1
            });
        })
        .with_config(move |config| {
            config.agent_inherit_full_access = enabled;
            config.features.enable(Feature::Collab).unwrap();
            if v2 {
                config.features.enable(Feature::MultiAgentV2).unwrap();
                config.multi_agent_v2.max_concurrent_threads_per_session = 2;
            } else {
                config.features.disable(Feature::MultiAgentV2).unwrap();
            }
            let role_path = config.codex_home.join("permission-worker.toml");
            std::fs::write(
                &role_path,
                "developer_instructions = 'Inspect the workspace.'\n",
            )
            .unwrap();
            config.agent_roles.insert(
                "permission_worker".into(),
                AgentRoleConfig {
                    description: Some("Permission test worker".into()),
                    config_file: Some(role_path.to_path_buf()),
                    nickname_candidates: None,
                },
            );
        });
    let test = builder.build_with_auto_env(&server).await?;
    let initial = test.codex.config_snapshot().await;
    let mut initial_child_id = None;

    for (prompt, child_prompt, call_id, task_name) in [
        (
            "start initial worker",
            "inspect initial workspace",
            "spawn-initial",
            "initial",
        ),
        (
            "start full access worker",
            "inspect full access workspace",
            "spawn-full",
            "full",
        ),
    ] {
        let args = if v2 {
            json!({"message": child_prompt, "task_name": task_name, "agent_type": "permission_worker", "fork_turns": "none"})
        } else {
            json!({"message": child_prompt, "agent_type": "permission_worker"})
        };
        let root_mock = responses::mount_sse_once_match(
            &server,
            move |request: &wiremock::Request| {
                body_contains(request, prompt) && !body_contains(request, call_id)
            },
            responses::sse(vec![
                responses::ev_response_created(call_id),
                responses::ev_function_call_with_namespace(
                    call_id,
                    if v2 {
                        "collaboration"
                    } else {
                        "multi_agent_v1"
                    },
                    "spawn_agent",
                    &args.to_string(),
                ),
                responses::ev_completed(call_id),
            ]),
        )
        .await;
        let child_mock = responses::mount_sse_once_match(
            &server,
            move |request: &wiremock::Request| {
                body_contains(request, child_prompt) && !body_contains(request, prompt)
            },
            responses::sse(vec![
                responses::ev_response_created(child_prompt),
                responses::ev_assistant_message("child-answer", "inspected"),
                responses::ev_completed(child_prompt),
            ]),
        )
        .await;
        let finish_mock = responses::mount_sse_once_match(
            &server,
            move |request: &wiremock::Request| {
                body_contains(request, prompt) && body_contains(request, call_id)
            },
            responses::sse(vec![
                responses::ev_response_created("root-finished"),
                responses::ev_assistant_message("root-answer", "worker started"),
                responses::ev_completed("root-finished"),
            ]),
        )
        .await;
        let previous_ids = test.thread_manager.list_thread_ids().await;
        test.submit_text_turn(prompt).await?;
        let child_id = test
            .thread_manager
            .list_thread_ids()
            .await
            .into_iter()
            .find(|id| !previous_ids.contains(id))
            .expect("spawned child");
        let child = test.thread_manager.get_thread(child_id).await?;
        wait_for_event(child.as_ref(), |event| {
            matches!(event, EventMsg::TurnComplete(_))
        })
        .await;
        assert!(!root_mock.requests().is_empty());
        assert!(!child_mock.requests().is_empty());
        assert!(!finish_mock.requests().is_empty());

        if task_name == "initial" {
            initial_child_id = Some(child_id);
            let before = child.config_snapshot().await;
            assert_eq!(
                (before.approval_policy, before.permission_profile.clone()),
                (initial.approval_policy, initial.permission_profile.clone())
            );
            test.codex
                .update_thread_settings(ThreadSettingsOverrides {
                    approval_policy: Some(AskForApproval::Never),
                    approvals_reviewer: Some(ApprovalsReviewer::User),
                    permission_profile: Some(PermissionProfile::Disabled),
                    ..Default::default()
                })
                .await?;
            let after = child.config_snapshot().await;
            let expected = if enabled {
                (AskForApproval::Never, PermissionProfile::Disabled, true)
            } else {
                (
                    before.approval_policy,
                    before.permission_profile,
                    before.full_access,
                )
            };
            assert_eq!(
                (
                    after.approval_policy,
                    after.permission_profile,
                    after.full_access
                ),
                expected
            );
        } else {
            let snapshot = child.config_snapshot().await;
            assert_eq!(
                (
                    snapshot.approval_policy,
                    snapshot.permission_profile,
                    snapshot.full_access
                ),
                (AskForApproval::Never, PermissionProfile::Disabled, true)
            );
            if enabled {
                test.codex
                    .update_thread_settings(ThreadSettingsOverrides {
                        approval_policy: Some(initial.approval_policy),
                        permission_profile: Some(initial.permission_profile.clone()),
                        ..Default::default()
                    })
                    .await?;
                let snapshot = child.config_snapshot().await;
                assert_eq!(
                    (snapshot.approval_policy, snapshot.permission_profile),
                    (initial.approval_policy, initial.permission_profile.clone())
                );
                if v2 {
                    let original_id = initial_child_id.unwrap();
                    assert!(test.thread_manager.get_thread(original_id).await.is_err());
                    test.thread_manager
                        .ensure_multi_agent_v2_child_loaded(original_id)
                        .await?;
                    let reloaded = test.thread_manager.get_thread(original_id).await?;
                    let snapshot = reloaded.config_snapshot().await;
                    assert_eq!(
                        (snapshot.approval_policy, snapshot.permission_profile),
                        (initial.approval_policy, initial.permission_profile.clone())
                    );
                }
            }
        }
    }
    Ok(())
}

#[tokio::test(flavor = "multi_thread", worker_threads = 2)]
async fn subagent_permissions_update_a_running_worker_before_its_next_tool() -> Result<()> {
    use std::sync::Arc;
    use std::time::Duration;
    use tokio::sync::Notify;

    let server = responses::start_mock_server().await;
    let mut builder = test_codex()
        .with_model_info_override("gpt-5.6-sol", |model| {
            model.multi_agent_version = Some(codex_protocol::protocol::MultiAgentVersion::V1);
            model.tool_mode = Some(codex_protocol::openai_models::ToolMode::Direct);
            model.apply_patch_tool_type =
                Some(codex_protocol::openai_models::ApplyPatchToolType::Freeform);
        })
        .with_config(|config| {
            config.agent_inherit_full_access = true;
            config.features.enable(Feature::Collab).unwrap();
            config.features.disable(Feature::MultiAgentV2).unwrap();
        });
    let test = builder.build_with_auto_env(&server).await?;
    let output_name = format!("../worker-full-access-{}.txt", uuid::Uuid::now_v7());
    let output_path = test.workspace_path_uri(&output_name)?;
    let root_mock = responses::mount_sse_once_match(
        &server,
        |request: &wiremock::Request| {
            body_contains(request, "start paused permission worker")
                && !body_contains(request, "spawn-paused")
        },
        responses::sse(vec![
            responses::ev_response_created("spawn-paused"),
            responses::ev_function_call_with_namespace(
                "spawn-paused",
                "multi_agent_v1",
                "spawn_agent",
                &json!({"message": "pause until permissions change"}).to_string(),
            ),
            responses::ev_completed("spawn-paused"),
        ]),
    )
    .await;
    let requested = Arc::new(Notify::new());
    let notify = Arc::clone(&requested);
    let patch_mock = responses::mount_response_once_match(
        &server,
        move |request: &wiremock::Request| {
            let matches = body_contains(request, "pause until permissions change")
                && !body_contains(request, "spawn-paused")
                && !body_contains(request, "write-after-permissions");
            if matches {
                notify.notify_one();
            }
            matches
        },
        responses::sse_response(responses::sse(vec![
            responses::ev_response_created("worker-write"),
            responses::ev_apply_patch_custom_tool_call("write-after-permissions",
                &format!("*** Begin Patch\n*** Add File: {}\n+written with inherited permissions\n*** End Patch\n", output_path.to_abs_path()?.display())),
            responses::ev_completed("worker-write"),
        ])).set_delay(Duration::from_secs(5)),
    ).await;
    let root_finish = responses::mount_sse_once_match(
        &server,
        |request: &wiremock::Request| body_contains(request, "spawn-paused"),
        responses::sse(vec![
            responses::ev_response_created("root-done"),
            responses::ev_assistant_message("root-done-message", "worker paused"),
            responses::ev_completed("root-done"),
        ]),
    )
    .await;
    let child_finish = responses::mount_sse_once_match(
        &server,
        |request: &wiremock::Request| body_contains(request, "write-after-permissions"),
        responses::sse(vec![
            responses::ev_response_created("worker-done"),
            responses::ev_assistant_message("worker-done-message", "written"),
            responses::ev_completed("worker-done"),
        ]),
    )
    .await;
    test.submit_text_turn("start paused permission worker")
        .await?;
    let child_id = test
        .thread_manager
        .list_thread_ids()
        .await
        .into_iter()
        .find(|id| *id != test.session_configured.thread_id)
        .expect("paused child");
    let child = test.thread_manager.get_thread(child_id).await?;
    tokio::time::timeout(Duration::from_secs(10), requested.notified()).await?;
    // Change permissions while the worker is awaiting its model response, before its next tool.
    tokio::time::timeout(
        Duration::from_secs(3),
        test.codex.update_thread_settings(ThreadSettingsOverrides {
            approval_policy: Some(AskForApproval::Never),
            approvals_reviewer: Some(ApprovalsReviewer::User),
            permission_profile: Some(PermissionProfile::Disabled),
            ..Default::default()
        }),
    )
    .await??;
    let snapshot = child.config_snapshot().await;
    assert_eq!(
        (
            snapshot.approval_policy,
            snapshot.permission_profile,
            snapshot.full_access
        ),
        (AskForApproval::Never, PermissionProfile::Disabled, true)
    );
    wait_for_event(child.as_ref(), |event| match event {
        EventMsg::TurnComplete(_) => true,
        EventMsg::Error(error) => panic!("worker failed: {}", error.message),
        EventMsg::ApplyPatchApprovalRequest(request) => {
            panic!("unexpected patch approval: {request:?}")
        }
        EventMsg::ExecApprovalRequest(request) => panic!("unexpected exec approval: {request:?}"),
        _ => false,
    })
    .await;
    let output = test
        .fs()
        .read_file(&output_path, Default::default(), /*sandbox*/ None)
        .await?;
    test.fs()
        .remove(
            &output_path,
            codex_file_system::RemoveOptions {
                recursive: false,
                force: true,
                follow_symlinks: true,
            },
            /*sandbox*/ None,
        )
        .await?;
    assert_eq!(output, b"written with inherited permissions\n".to_vec());
    assert!(!root_mock.requests().is_empty());
    assert!(!root_finish.requests().is_empty());
    assert!(!patch_mock.requests().is_empty());
    assert!(!child_finish.requests().is_empty());
    Ok(())
}
